"use client";

import { cn } from "@/registry/utilities/utils";
import { motion, useMotionValue, useSpring } from "motion/react";

// Credit:
// https://berlix.vercel.app/docs/flip-card

interface FlipCardProps {
	front: React.ReactNode;
	back: React.ReactNode;
	duration?: number;
	flipDirection?: "horizontal" | "vertical";
	flipRotation?: "forward" | "reverse";
	className?: string;
	panelClassName?: string;
}

export const FlipCard = ({
	front,
	back,
	duration = 0.3,
	className,
	panelClassName,
	flipDirection = "horizontal",
	flipRotation = "forward",
}: FlipCardProps) => {
	const rotate = useMotionValue(0);
	const rotateSpring = useSpring(rotate, {
		stiffness: (1 / duration) * 50,
		damping: 30,
	});

	const handleMouseEnter = () => {
		const isVertical = flipDirection === "vertical";
		const isForward = flipRotation === "forward";

		const angle = isVertical
			? isForward
				? -180
				: 180
			: isForward
				? 180
				: -180;

		rotate.set(angle);
	};
	const handleMouseLeave = () => rotate.set(0);

	const rotateStyle =
		flipDirection === "horizontal"
			? { rotateY: rotateSpring }
			: { rotateX: rotateSpring };

	const backfaceTransform =
		flipDirection === "horizontal" ? "rotateY(180deg)" : "rotateX(180deg)";

	return (
		<motion.div
			onMouseEnter={handleMouseEnter}
			onMouseLeave={handleMouseLeave}
			style={{
				perspective: 1000,
			}}
			className={cn("relative w-56 h-72", className)}
		>
			<motion.div
				style={{
					...rotateStyle,
					width: "100%",
					height: "100%",
					transformStyle: "preserve-3d",
					position: "relative",
				}}
			>
				<div
					className={cn(
						"absolute w-full h-full top-0 left-0 rounded-xl overflow-hidden shadow-md bg-white backface-hidden",
						panelClassName
					)}
				>
					{front}
				</div>

				<div
					style={{ transform: backfaceTransform }}
					className={cn(
						"absolute w-full h-full top-0 left-0  rounded-xl overflow-hidden shadow-md bg-white backface-hidden",
						panelClassName
					)}
				>
					{back}
				</div>
			</motion.div>
		</motion.div>
	);
};

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
